const express = require('express');
const BookRepository = require('../repository/bookRepository');

const router = express.Router();
const repo = new BookRepository();

router.post('/', (req, res) => {
  const { title, author } = req.body;
  res.status(201).json(repo.add(title, author));
});

router.get('/:id', async (req, res) => {
  // BUG: no try/catch. When findOrThrow rejects, the promise is unhandled,
  // Express never sends a response, and the request hangs forever.
  const book = await repo.findOrThrow(Number(req.params.id));
  res.json(book);
});

module.exports = router;

