const http = require('http');
function request(app, method, path, body) {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => {
      const port = server.address().port;
      const data = body === undefined ? null : JSON.stringify(body);
      const headers = data
        ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
        : {};
      const req = http.request(
        { host: '127.0.0.1', port, path, method, headers, timeout: 4000 },
        (res) => {
          let buf = '';
          res.on('data', (c) => (buf += c));
          res.on('end', () => {
            server.close();
            let json = null;
            try { json = JSON.parse(buf); } catch (e) { /* non-JSON */ }
            resolve({ status: res.statusCode, body: json, raw: buf });
          });
        }
      );
      req.on('timeout', () => { req.destroy(new Error('request timed out (handler never responded)')); });
      req.on('error', (e) => { server.close(); reject(e); });
      if (data) req.write(data);
      req.end();
    });
  });
}

const assert = require('assert');
const app = require('./src/app');

(async () => {
  let r = await request(app, 'POST', '/books', { title: 'Dune', author: 'Herbert' });
  assert.strictEqual(r.status, 201, r.raw);

  r = await request(app, 'GET', '/books/1');
  assert.strictEqual(r.status, 200, `valid id: ${r.status} ${r.raw}`);
  assert.strictEqual(r.body.title, 'Dune');

  // missing book -> 404 JSON, NOT a hang or a 500
  r = await request(app, 'GET', '/books/999');
  assert.strictEqual(r.status, 404, `missing book must be 404, got ${r.status} ${r.raw}`);
  assert(r.body && r.body.error, `404 must be JSON with error: ${r.raw}`);

  // bad id -> 400
  r = await request(app, 'GET', '/books/-3');
  assert.strictEqual(r.status, 400, `bad id must be 400, got ${r.status} ${r.raw}`);

  r = await request(app, 'GET', '/books/abc');
  assert.strictEqual(r.status, 400, `non-numeric id must be 400, got ${r.status} ${r.raw}`);
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

